widget.solution:
#include <cmath>
#include <vector>
// src/rates.cpp: the app has included include/pricing/rates.h above

namespace pricing {

double discount_factor(double r, double t) {
    return std::exp(-r * t);
}

double forward_price(double spot, double r, double t) {
    return spot / discount_factor(r, t);
}

double present_value(const std::vector<double>& cash, const std::vector<double>& times, double r) {
    double pv = 0;
    for (std::size_t i = 0; i < cash.size(); ++i) {
        pv += cash[i] * discount_factor(r, times[i]);
    }
    return pv;
}

}  // namespace pricing

